// Why: the system views mk ships are generated by a maintainer from pinned
// inputs; a view may hold only items a build can use, so the whole of every
// view must type-check, and the same inputs must give the same archives.
//
// What: SysGenOptions, SysGenView, SysGenResult and GenerateSystemViews,
// which runs the importer once per target over sysview.Table's rows (one
// translation unit, one import per row, the Microsoft flavour with mk's
// toolset headers), cuts the bindings into items, drops what only a shim
// defines and what does not check, and encodes one archive per view.
//
// How: the whole extracted text of every view is checked as the vendored C
// imports of a scratch package (pruning off), each a C-import module exactly
// as a build sees it; an item a diagnostic lands in is dropped with every
// item that needs it, and the check runs again until it is clean. A row
// whose input is absent is skipped with its reason.

package driver

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"sort"
	"strings"

	"mk/internal/cimport"
	"mk/internal/sysview"
	"mk/internal/toolchain"
)

// SysGenOptions are the inputs of GenerateSystemViews.
type SysGenOptions struct {
	// WindowsSDK is the Windows Kits\10 directory (or one Include\<version>
	// directory); "" skips the Windows SDK's rows.
	WindowsSDK string
	// Vulkan is Vulkan-Headers' include directory; "" skips the vulkan row.
	Vulkan string
	// Glibc are a Linux target's glibc include directories, by target.
	Glibc map[string]string
	// Tools is the toolchain; nil discovers it.
	Tools *toolchain.Tools
	// Log receives one line per step; nil is silent.
	Log func(format string, args ...any)
}

// SysGenView is one generated view.
type SysGenView struct {
	View    sysview.View
	Archive []byte
	Dropped []sysview.Dropped
	Stats   cimport.Stats
}

// SysGenResult is every generated view, by target then table order, and
// the rows skipped, each with its reason.
type SysGenResult struct {
	Views   []SysGenView
	Skipped []string
}

// maxCheckRounds bounds the drop-and-check loop; each round drops at least
// one item (a report holds one phase's diagnostics, so a later phase's
// show only once the earlier are gone).
const maxCheckRounds = 10

// GenerateSystemViews generates the archives of every row whose input
// o names.
func GenerateSystemViews(o SysGenOptions) (*SysGenResult, error) {
	logf := o.Log
	if logf == nil {
		logf = func(string, ...any) {}
	}
	tools := o.Tools
	if tools == nil {
		t, err := toolchain.Discover(toolchain.Options{})
		if err != nil {
			return nil, err
		}
		tools = t
	}
	res := &SysGenResult{}
	var targets []string
	for _, r := range sysview.Table {
		for _, t := range r.Targets {
			if !slices.Contains(targets, t) {
				targets = append(targets, t)
			}
		}
	}
	slices.Sort(targets)
	for _, target := range targets {
		var rows []sysview.Row
		var sysroot, inputs []string
		version := map[string]string{}
		for _, r := range sysview.ForTarget(target) {
			why := ""
			switch r.Input {
			case sysview.InputWindowsSDK:
				if o.WindowsSDK == "" {
					why = "no Windows SDK given (-sdk)"
					break
				}
				inc, v, err := windowsSDKInclude(o.WindowsSDK)
				if err != nil {
					return nil, err
				}
				if !slices.Contains(inputs, string(r.Input)) {
					sysroot = append(sysroot, windowsSDKDirs(inc)...)
					inputs = append(inputs, string(r.Input))
				}
				version[string(r.Input)] = v
			case sysview.InputVulkanHeaders:
				if o.Vulkan == "" || !isRegular(filepath.Join(o.Vulkan, "vulkan", "vulkan.h")) {
					why = "no Vulkan-Headers include directory given (-vulkan)"
					break
				}
				if !slices.Contains(inputs, string(r.Input)) {
					sysroot = append(sysroot, o.Vulkan)
					inputs = append(inputs, string(r.Input))
				}
				version[string(r.Input)] = "unversioned"
			case sysview.InputGlibc:
				d := o.Glibc[target]
				if d == "" {
					why = "no glibc headers given for " + target
					break
				}
				if !slices.Contains(inputs, string(r.Input)) {
					sysroot = append(sysroot, d)
					inputs = append(inputs, string(r.Input))
				}
				version[string(r.Input)] = "unversioned"
			}
			for _, q := range r.RequiresFor(target) {
				if !slices.ContainsFunc(rows, func(x sysview.Row) bool { return x.Name == q }) && why == "" {
					why = "it requires " + q + ", which is skipped"
				}
			}
			if why != "" {
				res.Skipped = append(res.Skipped, fmt.Sprintf("%s for %s: skipped: %s", r.Name, target, why))
				logf("skip c.%s for %s: %s", r.Name, target, why)
				continue
			}
			rows = append(rows, r)
		}
		if len(rows) == 0 {
			continue
		}
		views, err := generateTarget(tools, target, rows, sysroot, version, logf)
		if err != nil {
			return nil, err
		}
		res.Views = append(res.Views, views...)
	}
	return res, nil
}

// generateTarget translates rows (one target's, in table order) as one
// unit and returns their checked views.
func generateTarget(tools *toolchain.Tools, target string, rows []sysview.Row, sysroot []string, version map[string]string, logf func(string, ...any)) ([]SysGenView, error) {
	ctx := context.Background()
	rd, err := tools.ResourceDir(ctx)
	if err != nil {
		return nil, err
	}
	work, err := os.MkdirTemp("", "mk-sysview-")
	if err != nil {
		return nil, err
	}
	defer os.RemoveAll(work)
	sys, err := cimport.SystemFor(target, sysroot, filepath.Join(work, "msvch"))
	if err != nil {
		return nil, err
	}
	var imports []cimport.Import
	names := make([]string, len(rows))
	for i, r := range rows {
		names[i] = r.Name
		imports = append(imports, cimport.Import{Name: r.Name, Headers: r.Headers, Defines: r.DefinesFor(target)})
	}
	logf("translate %s for %s (%s flavour, triple %s)", strings.Join(names, ", "), target, sys.Flavour, sys.Triple)
	tr, err := cimport.Translate(ctx, tools, rd, cimport.Request{Target: target, Triple: sys.Triple, Imports: imports,
		Sysroot: sys.Dirs, WorkDir: filepath.Join(work, "tu")})
	if err != nil {
		return nil, err
	}
	views, drop := cimport.ViewItems(names, tr.Modules, tr.ShimFuncs)
	for i, v := range views {
		want := rows[i].RequiresFor(target)
		for _, q := range v.Meta.Requires {
			if !slices.Contains(want, q) {
				return nil, fmt.Errorf("sysview: c.%s for %s refers to c.%s, which its row does not require: add it to the table's Requires", v.Meta.Name, target, q)
			}
		}
	}
	var dropped []sysview.Dropped
	views, dropped, err = sysview.DropItems(views, drop)
	if err != nil {
		return nil, err
	}
	for round := 1; ; round++ {
		bad, err := checkWholeViews(tools, target, views)
		if err != nil {
			return nil, err
		}
		n := 0
		for _, d := range bad {
			n += len(d)
		}
		logf("check %s for %s, round %d: %d item(s) do not check", strings.Join(names, ", "), target, round, n)
		if n == 0 {
			break
		}
		if round == maxCheckRounds {
			return nil, fmt.Errorf("sysview: the views for %s still do not check after %d rounds", target, round)
		}
		var more []sysview.Dropped
		views, more, err = sysview.DropItems(views, bad)
		if err != nil {
			return nil, err
		}
		dropped = append(dropped, more...)
	}
	out := make([]SysGenView, len(views))
	for i, v := range views {
		r := rows[i]
		in := map[string]string{"importer": cimport.ImporterFormat, "clang": tools.Version.String(),
			string(r.Input): version[string(r.Input)]}
		if sys.Flavour == cimport.FlavourMicrosoft {
			in["toolset-headers"] = cimport.ToolsetHeadersHash()
		}
		st := tr.Stats[i]
		var mine []sysview.Dropped
		for _, d := range dropped {
			if d.View == v.Meta.Name {
				mine = append(mine, d)
			}
		}
		v.Meta.Target, v.Meta.Headers, v.Meta.Defines, v.Meta.Inputs = target, r.Headers, r.DefinesFor(target), in
		v.Meta.Counts = map[string]int{"declarations": st.Decls, "bound": st.Bound(), "items": len(v.Items), "dropped": len(mine)}
		data, err := sysview.Write(v.Meta, v.Items, sysview.DefaultOptions)
		if err != nil {
			return nil, err
		}
		out[i] = SysGenView{View: v, Archive: data, Dropped: mine, Stats: st}
		logf("c.%s for %s: %d items, %d dropped, %d bytes", v.Meta.Name, target, len(v.Items), len(mine), len(data))
	}
	return out, nil
}

// checkWholeViews checks every item of views (one target's) and returns the
// items a diagnostic lands in, by view and index, with the diagnostic's
// message. The views are the vendored C imports of a scratch package whose
// headers do not exist, so the vendored text is what is read.
func checkWholeViews(tools *toolchain.Tools, target string, views []sysview.View) (map[string]map[int]string, error) {
	set := sysview.Set{}
	for _, v := range views {
		data, err := sysview.Write(v.Meta, v.Items, sysview.DefaultOptions)
		if err != nil {
			return nil, err
		}
		a, err := sysview.Open(data)
		if err != nil {
			return nil, err
		}
		set[v.Meta.Name] = a
	}
	mods, err := sysview.Extract(set, nil, true)
	if err != nil {
		return nil, err
	}
	byName := map[string]sysview.Module{}
	for _, m := range mods {
		byName[m.Name] = m
	}
	dir, err := os.MkdirTemp("", "mk-sysview-check-")
	if err != nil {
		return nil, err
	}
	defer os.RemoveAll(dir)
	var imports []string
	for _, v := range views {
		imports = append(imports, fmt.Sprintf("pkg.CImport(name: %q, headers: [\"mk_sysview_absent_%s.h\"], defines: [], macros: [], vendor: true, include_dirs: [])", v.Meta.Name, v.Meta.Name))
		p := filepath.Join(dir, "gen", target, "c", v.Meta.Name+".mk")
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			return nil, err
		}
		if err := os.WriteFile(p, cViewBytes(byName[v.Meta.Name].Text, target), 0o644); err != nil {
			return nil, err
		}
	}
	man := "const Package = pkg.Package(\n    name: \"sysviewcheck\",\n    bins: [pkg.Bin(name: \"sysviewcheck\", root: \"app\", link_script: \"\", cpu: \"\", subsystem: \"console\")],\n" +
		"    deps: [],\n    c_sources: [],\n    c_imports: [" + strings.Join(imports, ", ") + "],\n    asm_sources: [],\n    targets: [],\n    unsafe_modules: [],\n    links: [],\n)\n"
	main := "export Main(sys: &System): WriteError!void {\n    try sys.Print(\"ok\\n\", ())\n}\n"
	if err := os.WriteFile(filepath.Join(dir, "pkg.mk"), []byte(man), 0o644); err != nil {
		return nil, err
	}
	if err := os.MkdirAll(filepath.Join(dir, "app"), 0o755); err != nil {
		return nil, err
	}
	if err := os.WriteFile(filepath.Join(dir, "app", "main.mk"), []byte(main), 0o644); err != nil {
		return nil, err
	}
	tg, _, ok := TargetNamed(target)
	if !ok {
		return nil, fmt.Errorf("sysview: unknown target %s", target)
	}
	cfg := Config{Root: dir, Target: tg, Tools: tools, NoCache: true, MaxDiags: 1 << 20}
	cfg.TestHooks.CImportWhole = true
	s, err := NewSession(cfg)
	if err != nil {
		return nil, err
	}
	r := s.Check()
	bad := map[string]map[int]string{}
	var loose []string
	prefix := "gen/" + target + "/c/"
	for _, e := range r.Report.Diags {
		d := e.Diag
		f := r.Sources.File(d.At.File)
		if f == nil || !strings.Contains(f.Path, prefix) {
			loose = append(loose, d.Message)
			continue
		}
		name := strings.TrimSuffix(f.Path[strings.LastIndex(f.Path, prefix)+len(prefix):], ".mk")
		m, ok := byName[name]
		if !ok {
			loose = append(loose, d.Message)
			continue
		}
		line := int(f.LineCol(d.At.Start).Line)
		k := sort.SearchInts(m.Lines, line+1) - 1
		if k < 0 {
			loose = append(loose, fmt.Sprintf("%s:%d: %s", f.Path, line, d.Message))
			continue
		}
		if bad[name] == nil {
			bad[name] = map[int]string{}
		}
		if _, seen := bad[name][m.Items[k]]; !seen {
			bad[name][m.Items[k]] = fmt.Sprintf("does not check: %s %s", d.Code, d.Message)
		}
	}
	if len(loose) > 0 {
		return nil, fmt.Errorf("sysview: the check of the views for %s failed outside any item:\n%s", target, strings.Join(loose, "\n"))
	}
	return bad, nil
}
